&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;strong&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;&amp;ldquo;İKTİDAR YOKSULLUKLA M&amp;Uuml;CADELE EDEMEYİNCE MİLLETİ YOKSULLUĞA İKNA ETMEYE &amp;Ccedil;ALIŞIYOR&amp;rdquo;&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;&amp;ldquo;Sayın Erdoğan Asgari &amp;uuml;cret konuşulurken taşın altına elinizi koyun &amp;ccedil;ağrısı yapmıştı. Şimdi bizde aynı &amp;ccedil;ağrıyı sayın Erdoğan&amp;rsquo;a yapıyoruz. Sayın Erdoğan elinizi taşın altına koyma sırası sizde! Elbette sadece &amp;ccedil;ağrı ile yetinmiyoruz, &amp;Ouml;nceki g&amp;uuml;n; İktidarı harekete ge&amp;ccedil;irmek i&amp;ccedil;in,&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;En d&amp;uuml;ş&amp;uuml;k emekli maaşının, asgari &amp;uuml;cret seviyesine &amp;ccedil;ıkarılmasına dair kanun teklifimizi T&amp;uuml;rkiye B&amp;uuml;y&amp;uuml;k Millet Meclisi&amp;rsquo;ne sunduk. Başta iktidar partileri olmak &amp;uuml;zere meclisteki t&amp;uuml;m partileri bu kanun teklifimize destek vermeye davet ediyoruz. Aziz milletimizi de, Kanun teklifimize&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;İmza vererek, destek olmaya &amp;ccedil;ağırıyoruz! Emeklimiz bu &amp;uuml;lkenin y&amp;uuml;k&amp;uuml; değil bereketidir.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Cefayı değil vefayı hak ediyorlar. Emin olun emeklimize verilecek her kuruş bu &amp;uuml;lkenin &amp;uuml;zerine rahmet, bereket ve dua olarak d&amp;ouml;necektir.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Bizler;Bu &amp;uuml;lke i&amp;ccedil;in &amp;ccedil;alışmış, emeklilerimizin hakkettikleri insanca yaşam &amp;uuml;cretini almaları i&amp;ccedil;in b&amp;uuml;t&amp;uuml;n g&amp;uuml;c&amp;uuml;m&amp;uuml;zle bundan &amp;ouml;nce olduğu gibi bundan sonra da &amp;ccedil;alışmaya devam edeceğiz!&amp;rdquo;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;h1 style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:20pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Calibri Light&amp;quot;,sans-serif&quot;&gt;&lt;span style=&quot;color:#2f5496&quot;&gt;&lt;a name=&quot;_Toc218620697&quot;&gt;&lt;strong&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;&amp;ldquo;STRATEJİK ALAN: TARIM&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/a&gt;&lt;strong&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;&amp;rdquo;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/h1&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;&amp;ldquo;B&amp;ouml;lgemizdeki ve d&amp;uuml;nyadaki gelişmeler tarımın ne kadar stratejik,&amp;nbsp;&amp;nbsp;gıdada bağımsızlığın ne kadar hayati olduğunu a&amp;ccedil;ık&amp;ccedil;a g&amp;ouml;stermiştir. &amp;Uuml;lkemizi tarımda, hayvancılıkta, &amp;uuml;retimde yeniden kendi kendine yetebilen bir &amp;uuml;lke haline getirmek beka meselesidir. Peki &amp;uuml;lkemizi y&amp;ouml;netenlerde bu feraset ve anlayışı g&amp;ouml;rebiliyor muyuz? Tablo ortada; 2025 yılında en &amp;ccedil;ok zarar eden alanların başında tarım sekt&amp;ouml;r&amp;uuml; geliyor.&amp;nbsp;&amp;nbsp;2025 &amp;ccedil;ift&amp;ccedil;imiz i&amp;ccedil;in adeta iflas yılı oldu.&amp;nbsp;&amp;nbsp;Don, kuraklık ve t&amp;uuml;rl&amp;uuml; sorunlarla uğraşan &amp;ccedil;ift&amp;ccedil;imiz; en b&amp;uuml;y&amp;uuml;k darbeyi iktidarın ekonomi politikasından yedi. D&amp;uuml;ş&amp;uuml;n&amp;uuml;n;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Kadir amcamız 100 d&amp;ouml;n&amp;uuml;m soğan ekiyor.&amp;nbsp;&amp;nbsp;G&amp;uuml;bre, tohum, mazot, ila&amp;ccedil;, iş&amp;ccedil;ilik derken;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Kadir amcamız bu girdileri karşılayabilmek i&amp;ccedil;in bankadan faizle kredi alıyor.&amp;nbsp;&amp;nbsp;Yetmiyor; ektiği soğan don ve kuraklıktan da etkileniyor. Yıl sonuna gelince Kadir Amcamız faizi &amp;ouml;deyebilmek i&amp;ccedil;in ya tarlasını ya da trakt&amp;ouml;r&amp;uuml;n&amp;uuml; satmak zorunda kalıyor. Peki iktidar ne yapıyor?&amp;nbsp;&amp;nbsp;Bu &amp;uuml;lke i&amp;ccedil;in adeta bir kahraman gibi yaşatılması gereken &amp;ccedil;ift&amp;ccedil;imizin değil, faiz lobisinin yanında duruyor.&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Bakınız; 2026 b&amp;uuml;t&amp;ccedil;esinde faize ayrılan para 2.7 trilyon ile b&amp;uuml;t&amp;ccedil;enin yaklaşık %14.5&amp;rsquo;i. Başka bir deyişle; aziz milletimizden toplanacak olan verginin %18&amp;rsquo;i faize gidecek. Peki, tarıma ayrılan destek ne kadar?&amp;nbsp;&amp;nbsp;Sadece 168 milyar TL. Yani faize ayrılan paranın 16&amp;rsquo;da biri.&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Şimdi biz iktidardan şunun cevabını bekliyoruz; sizin i&amp;ccedil;in İngiltere&amp;rsquo;nin, ABD&amp;rsquo;nin faiz lobileri mi daha &amp;ouml;nemli yoksa &amp;ccedil;ift&amp;ccedil;imiz mi? Sizin &amp;ouml;nceliğiniz faiz mi yoksa bereketli topraklarımız mı?&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Ziraat Bankasından kredi alıp medya g&amp;uuml;c&amp;uuml; elde edenlerin kredilerini 10 yıl ertelerken; gariban k&amp;ouml;yl&amp;uuml; kredilerini birka&amp;ccedil; ay geciktirince neden gelirine haciz koyuyorsunuz?&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Sizin i&amp;ccedil;in trolluk yapanlar, bu &amp;uuml;lkenin toprağını bereketlendiren k&amp;ouml;yl&amp;uuml;m&amp;uuml;zden, &amp;ccedil;ift&amp;ccedil;imizden daha mı değerli? İşte beka sorunu dediğimiz budur arkadaşlar. Biz buradan s&amp;ouml;z veriyoruz;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Saadet Partisi iktidarında para faize değil, &amp;ccedil;ift&amp;ccedil;imize, &amp;uuml;reticimize gidecek.&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Bizim iktidarımızda, Ziraat Bankasının kredileri medya patronlarına değil; &amp;ccedil;ift&amp;ccedil;imize verilecek.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Milletin ve hakikatin arasına Demir &amp;ouml;renlere değil, soğan ekenlere verilecek.&amp;rdquo;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

